     ///
     /// Allocates a frame.
     ///
     /// # Returns
     ///
     /// Upon success, the address of the allocated frame is returned. Upon failure, an error is
     /// returned instead.
     ///
     #[verus_spec(result =>
         requires
             old(self).inv(),
         ensures
             final(self).inv(),
